import {DOODLE_SHAPES} from './doodle-core.js';
export function placementInk(shape){const s=DOODLE_SHAPES.find(s=>s.id===shape);return s?Math.round(s.cost*(.65+(shape==='wall'?Math.hypot(50,50):50)/130)):0;}
export function defenseStatus(m){if(m.kind==='castle'){if(m.phase==='build'){const unsupported=m.items.length-m.supports().size;return unsupported?`${unsupported} unsupported piece(s) · connect them to grounded supports before the siege`:`${m.items.length} supported pieces · ${m.plannedCount()} enemies next · ${m.preparingNext?'repair and reinforce, then start the next assault':'build defenses, then START SIEGE'}`;}return `${m.enemyRemaining} enemies remaining · ${Math.ceil(m.coreHP)} king health · ${m.attack?'tap to fire at defenses':'activate traps or repair when needed'}`;}if(m.tool==='upgrade')return 'Tap a defense to upgrade · 25 ink · maximum level 3';if(m.tool==='place'){const cost=placementInk(m.selectedShape),shape=DOODLE_SHAPES.find(s=>s.id===m.selectedShape);return `${shape?.name||'Choose a shape'} · placement costs ${cost} ink · ${m.ink>=cost?'tap the notebook to place':'wait for ink to refill'}`;}const shape=DOODLE_SHAPES.find(s=>s.id===m.selectedShape);const jobs={turret:'fires bullets at nearby enemies',mine:'single-use explosion when enemies approach',healer:'sends green healing pluses to damaged defenses or nearby HOME',wall:'blocks ground enemies',shield:'absorbs enemy attacks',shock:'zaps nearby enemies',slow:'slows nearby enemies',star:'temporary power burst and turret boost'};return 'Draw '+(shape?.name||'a defense')+' your way · '+jobs[m.selectedShape]+' · size affects ink';}
export function defenseIcon(id){const shape=id.replace('shape:',''),paths={wall:'M12 43L52 21',shield:'M52 32a20 20 0 1 1-40 0a20 20 0 1 1 40 0',turret:'M32 10L56 52H8Z',shock:'M8 46L18 18L28 46L38 18L48 46L56 24',slow:'M32 32c-12-12-24 12-5 17c28 6 35-35 5-38c-22-2-29 20-23 34',star:'M32 7L39 24L58 25L43 37L48 57L32 45L16 57L21 37L6 25L25 24',mine:'M12 42H52L45 25H19ZM32 25V12M22 12H42',healer:'M32 12V52M12 32H52',draw:'M14 49L20 35L45 10L55 20L30 45Z',place:'M14 8L50 35L33 38L26 55Z',upgrade:'M32 54V12M14 30L32 12L50 30'};return `<svg viewBox="0 0 64 64" aria-hidden="true"><path d="${paths[shape]||paths.draw}" fill="none" stroke="currentColor" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;}
export function drawNotebook(c){c.fillStyle='#d8d6c0';c.fillRect(0,0,1000,640);c.fillStyle='#eeead7';c.fillRect(65,24,825,590);c.strokeStyle='#889eaa45';c.lineWidth=1;for(let y=70;y<610;y+=32){c.beginPath();c.moveTo(67,y);c.lineTo(888,y);c.stroke();}c.strokeStyle='#be7e7b88';c.beginPath();c.moveTo(100,24);c.lineTo(100,614);c.stroke();for(let y=55;y<610;y+=55){c.fillStyle='#9aa9a0';c.beginPath();c.arc(75,y,7,0,Math.PI*2);c.fill();c.strokeStyle='#536b73';c.lineWidth=3;c.beginPath();c.ellipse(64,y,16,5,0,0,Math.PI*2);c.stroke();}c.fillStyle='#566c68';c.font='600 14px Outfit, sans-serif';c.textAlign='center';c.fillText('THE SKETCHBOOK GUARD · DRAW A DEFENSE',490,49);}
export function drawCastleScenery(c){c.save();c.fillStyle='#456d642b';for(const x of [20,880]){c.fillRect(x,315,72,135);c.fillRect(x-8,305,88,20);for(let i=0;i<4;i++)c.fillRect(x-8+i*25,290,16,18);c.fillStyle='#d8e2b44d';c.fillRect(x+26,340,20,35);c.fillStyle='#456d642b';}c.strokeStyle='#c2b89755';c.lineWidth=3;c.beginPath();c.moveTo(0,550);c.bezierCurveTo(200,500,800,535,1000,510);c.stroke();c.restore();}
